						}
					}

					#Ruler traits
					modifier = {
						add = -20
						count_owned_leader = {
							limit = {
								has_leader_flag = thesis_team
								has_trait_tier1or2 = { TRAIT = leader_trait_substance_abuser }
							}
							count > 1
						}
					}

					#Empire tech level
					modifier = {
						add = 40
						federation = {
							count_member = {
								limit = {
									NOT = { is_same_value = prevprev }
									relative_power = {
										who = prevprev
										category = technology
										value > equivalent
									}
								}
								count = 0
							}
						}
					}
					modifier = {
						add = 30
						federation = {
							count_member = {
								limit = {
									NOT = { is_same_value = prevprev }
									relative_power = {
										who = prevprev
										category = technology
										value > inferior
									}
								}
								count = 0
							}
						}
					}
					modifier = {
						add = trigger:num_repeatable_techs
						always = yes
					}
					modifier = {
						add = 20
						federation = {
							count_member = {
								limit = {
									relative_power = {
										who = prevprev
										category = technology
										value > equivalent
									}
								}
								count = 1
							}
							count_member = {
								limit = {
									relative_power = {
										who = prevprev
										category = technology
										value < equivalent
									}
								}
								count > 1
							}
						}
					}
					modifier = {
						factor = 0.1
						federation = {
							any_member = {
								NOT = { is_same_value = prevprev }
								relative_power = {
									who = prevprev
									category = technology
									value = overwhelming
